const NO_REPEAT_WORD = ['id','ms','fil','vi','th','ko','ja','zh','zh_cn','zh_tw'];
const LEGIT_TRIPLE = ['schifffahrt','rollladen','stilllegung','stillleben','brennnessel',
  'schneeeule','kaffeeersatz','kaffeeernte','betttuch','balletttanz','sauerstoffflasche',
  'fussballliga','nulllinie','volllast','helllicht','sperrrad','fetttropf',
  'flussschiff','kunststofffenster','sammelllinse','schlussstrich','stofffarbe','jaaaar'];

function legitTriple(low) {
  for (const w of LEGIT_TRIPLE) { if (low.indexOf(w) !== -1) { return true; } }
  return false;
}
function stripNoise(s) {
  return String(s)
    .replace(/<[^>]*>/g, ' ')
    .replace(/https?:\/\/\S+/g, ' ')
    .replace(/\S+@\S+\.\S+/g, ' ')
    .replace(/\[%[^\]]*\]/g, ' ')
    .replace(/%\d+\$[a-zA-Z]/g, ' ')
    .replace(/%[sdioxfeguc@]/g, ' ')
    .replace(/\{\{[^}]*\}\}/g, ' ')
    .replace(/\{[^}]*\}/g, ' ')
    .replace(/\[[^\]]*\]/g, ' ')
    .replace(/&[a-zA-Z]+;/g, ' ')
    .replace(/&#\d+;/g, ' ')
    .replace(/\$\w+/g, ' ')
    .replace(/:\w+:/g, ' ');
}
function tokenize(s) {
  const parts = String(s).split(/[^\p{L}\p{M}]+/u);
  const out = [];
  for (const p of parts) { if (p.length > 0) { out.push(p); } }
  return out;
}
function isAllUpper(t) { return t === t.toUpperCase() && /\p{L}/u.test(t); }
function isPseudo(iso) {
  const s = (iso || '').toLowerCase();
  return s === 'pst' || s.indexOf('pseudo') >= 0;
}
function findTypos(text, iso, srcSet) {
  const findings = [];
  const clean = stripNoise(text);
  for (const tok of tokenize(clean)) {
    const low = tok.toLowerCase();
    if (srcSet[low]) { continue; }
    if (tok.length >= 4 && !isAllUpper(tok) && !legitTriple(low) && /(\p{L})\1\1/u.test(tok)) {
      findings.push({ rule: 'triple_letter', token: tok });
      continue;
    }
    if (/\p{Script=Latin}/u.test(tok) && /\p{Script=Cyrillic}|\p{Script=Greek}/u.test(tok)) {
      findings.push({ rule: 'mixed_script', token: tok });
      continue;
    }
  }
  if (NO_REPEAT_WORD.indexOf(iso) === -1) {
    const m = clean.match(/(?<!\p{L})(\p{L}{2,})[ \u00A0]+\1(?!\p{L})/giu);
    if (m) { for (const hit of m) { findings.push({ rule: 'repeated_word', token: hit.replace(/\s+/g, ' ').trim() }); } }
  }
  return findings;
}
function keyName(k) {
  const n = k.key_name;
  if (typeof n === 'string') { return n; }
  if (n && typeof n === 'object') { return n.web || n.other || n.ios || n.android || String(k.key_id); }
  return String(k.key_id);
}

const meta = $('Page Input').first().json;
const baseLang = (meta.base_lang || 'en').toLowerCase();
const r = $input.first().json || {};
const ok = r.statusCode === 200;
const keys = (ok && r.body && r.body.keys) ? r.body.keys : [];
const rows = [];
let examined = 0;

for (const k of keys) {
  if (k.is_archived) { continue; }
  examined++;
  const trs = k.translations || [];
  const srcSet = {};
  let srcText = '';
  for (const tr of trs) {
    if ((tr.language_iso || '').toLowerCase() === baseLang) {
      srcText = typeof tr.translation === 'string' ? tr.translation : '';
      for (const t of tokenize(stripNoise(srcText))) { srcSet[t.toLowerCase()] = 1; }
    }
  }
  for (const tr of trs) {
    const iso = (tr.language_iso || '').toLowerCase();
    if (iso === baseLang) { continue; }
    if (isPseudo(iso)) { continue; }
    if (tr.is_untranslated) { continue; }
    const v = tr.translation;
    if (typeof v !== 'string' || v.length === 0) { continue; }
    const hits = findTypos(v, iso, srcSet);
    for (const h of hits) {
      rows.push({
        project: meta.project_name,
        project_id: meta.project_id,
        lang: iso,
        key: keyName(k),
        key_id: k.key_id,
        rule: h.rule,
        token: h.token,
        target: v.length > 300 ? v.slice(0, 300) + '…' : v,
        source: srcText.length > 300 ? srcText.slice(0, 300) + '…' : srcText,
        is_reviewed: tr.is_reviewed ? 1 : 0
      });
    }
  }
}

return [{ json: {
  project: meta.project_name,
  project_id: meta.project_id,
  page: meta.page,
  ok: ok,
  status: r.statusCode,
  keys_examined: examined,
  finding_count: rows.length,
  rows: rows
}}];
